import { generateSecret as otpGenerateSecret, generateSync, verifySync, generateURI } from "otplib";
import QRCode from "qrcode";

const APP_NAME = "SecureBank";

export function generateTotpSecret(): string {
  return otpGenerateSecret();
}

export function verifyTotpCode(secret: string, code: string): boolean {
  try {
    const result = verifySync({ secret, token: code, strategy: "totp" });
    return result === true;
  } catch {
    return false;
  }
}

export async function getTotpQrCode(email: string, secret: string): Promise<string> {
  const uri = generateURI({ strategy: "totp", issuer: APP_NAME, label: email, secret });
  return QRCode.toDataURL(uri);
}
